def _apply_preemptive_decision_context(
    *,
    intent: dict[str, Any],
    allocation: dict[str, Any],
    preemptive_decision: dict[str, Any],
) -> None:
    intent["preemptive_edge_control"] = preemptive_decision
    allocation["preemptive_edge_control"] = preemptive_decision
    model_inputs = allocation.get("model_inputs") if isinstance(allocation.get("model_inputs"), dict) else {}
    if model_inputs is not allocation.get("model_inputs"):
        allocation["model_inputs"] = model_inputs
    preserve_source_loss_probability = (
        _paper_exploration_should_preserve_source_loss_probability(intent)
    )
    source_loss_probability = intent.get("pre_trade_loss_probability")
    for field in PREEMPTIVE_DECISION_CONTEXT_FIELDS:
        if field in preemptive_decision:
            if field == "pre_trade_loss_probability" and preserve_source_loss_probability:
                runtime_value = preemptive_decision[field]
                source_label = (
                    "strategy_supply_calibrated_materialization_queue"
                    if intent.get("materialization_queue_id")
                    else "strategy_supply_calibrated_inventory"
                )
                for target in (intent, allocation, model_inputs):
                    target["pre_trade_loss_probability"] = source_loss_probability
                    target["runtime_revalidated_pre_trade_loss_probability"] = runtime_value
                    target["pre_trade_loss_probability_source"] = _first_present(
                        target.get("pre_trade_loss_probability_source"),
                        source_label,
                    )
                    target["runtime_revalidated_loss_probability_source"] = (
                        "paper_loop_preemptive_recompute"
                    )
                continue
            intent[field] = preemptive_decision[field]
            allocation[field] = preemptive_decision[field]
            model_inputs[field] = preemptive_decision[field]
    if preserve_source_loss_probability or intent.get("materialization_queue_id"):
        runtime_reasons = preemptive_decision.get("preemptive_decision_reasons")
        runtime_reasons_list = _string_list(runtime_reasons)
        for target in (intent, allocation, model_inputs):
            target["runtime_revalidated_preemptive_decision"] = (
                preemptive_decision.get("preemptive_decision")
            )
            target["runtime_revalidated_preemptive_decision_id"] = (
                preemptive_decision.get("preemptive_decision_id")
            )
            target["runtime_revalidated_preemptive_decision_reasons"] = (
                runtime_reasons_list
            )


def _preemptive_decision_rejection_reason_for_tier(
    preemptive_decision: dict[str, Any] | None,
    *,
    paper_tier: Any,
) -> str | None:
    if not isinstance(preemptive_decision, dict) or not preemptive_decision.get(
        "preemptive_decision_id"
    ):
        return "PREEMPTIVE_DECISION_MISSING_FAIL_CLOSED"
    decision = str(preemptive_decision.get("preemptive_decision") or "").upper()
    if paper_tier == PAPER_TIER_A_PLUS_BOOTSTRAP_REDUCED_SIZE:
        if decision in {"ALLOW", "REDUCE_SIZE_PAPER_ONLY"}:
            return None
        return f"PREEMPTIVE_DECISION_DENIES_REDUCED_SIZE:{decision or 'MISSING'}"
    if paper_tier == PAPER_TIER_POSITIVE_EDGE_PROBATION:
        if decision in {"ALLOW", "POSITIVE_EDGE_PROBATION_PAPER"}:
            return None
        return f"PREEMPTIVE_DECISION_DENIES_PROBATION:{decision or 'MISSING'}"
    if paper_tier == PAPER_TIER_RISK_CONTROLLER_EXPLORATION:
        if decision in {
            "ALLOW",
            "POSITIVE_EDGE_PROBATION_PAPER",
            "REDUCE_SIZE_PAPER_ONLY",
            "PAPER_RISK_CONTROLLER_EXPLORATION",
        }:
            return None
        if decision == "NO_TRADE":
            return "PREEMPTIVE_DECISION_NO_TRADE_REQUIRES_EXPLORATION_POLICY_OVERRIDE"
        return f"PREEMPTIVE_DECISION_DENIES_PAPER_RISK_CONTROLLER_EXPLORATION:{decision or 'MISSING'}"
    if decision == "ALLOW":
        return None
    return f"PREEMPTIVE_DECISION_DENIES_ENTRY:{decision or 'MISSING'}"


def _paper_preemptive_admission_rejection_reasons(intent: dict[str, Any], redis_client: Any = None) -> list[str]:
    reasons: list[str] = []
    paper_tier = str(intent.get("paper_opportunity_tier") or "").strip().upper()
    tier_rejection = _preemptive_decision_rejection_reason_for_tier(
        intent.get("preemptive_edge_control"),
        paper_tier=paper_tier,
    )
    if (
        tier_rejection
        and not (
            paper_tier == PAPER_TIER_RISK_CONTROLLER_EXPLORATION
            and tier_rejection
            == "PREEMPTIVE_DECISION_NO_TRADE_REQUIRES_EXPLORATION_POLICY_OVERRIDE"
            and intent.get("paper_risk_controller_exploration_eligible") is True
        )
    ):
        reasons.append(tier_rejection)
    loss_probability = _coerce_float(intent.get("pre_trade_loss_probability"))
    if loss_probability is None:
        # Adaptive: instead of fail-closed, allow if confidence is sufficiently high
        # (e.g., trainer hasn't calculated loss probability yet, but model confidence is strong)
        confidence = _coerce_float(intent.get("confidence_calibrated"))
        if confidence is not None and confidence >= 0.75:
            pass  # High confidence overrides missing loss probability
        else:
            reasons.append("PRE_TRADE_LOSS_PROBABILITY_MISSING_ALLOW_HIGH_CONFIDENCE_ONLY")
    else:
        adaptive_loss_prob_threshold = 0.80
        if redis_client:
            try:
                tuning_state = redis_client.get("v2:orchestrator:adaptive_gate_tuning_state")
                if tuning_state:
                    tuning_data = json.loads(tuning_state)
                    adaptive_loss_prob_threshold = tuning_data.get("adaptive_loss_probability_threshold", 0.80)
            except Exception:
                pass
        if loss_probability >= adaptive_loss_prob_threshold:
            reasons.append("PRE_TRADE_LOSS_PROBABILITY_ABOVE_ALLOWED_BOUND")
    if (
        paper_tier == PAPER_TIER_RISK_CONTROLLER_EXPLORATION
        and loss_probability is not None
        and loss_probability >= PAPER_RISK_CONTROLLER_EXPLORATION_LOSS_PROBABILITY_BOUND
    ):
        reasons.append("PAPER_RISK_CONTROLLER_EXPLORATION_LOSS_PROBABILITY_ABOVE_BOUND")
    if paper_tier == PAPER_TIER_A_PLUS_BOOTSTRAP_REDUCED_SIZE:
        if intent.get("continuous_edge_guardian_new_entries_allowed") is not True:
            reasons.append("REDUCE_SIZE_FILL_LACKS_GUARDIAN_APPROVAL")
    guardian_state = str(
        _first_present(
            intent.get("continuous_edge_guardian_status"),
            intent.get("paper_performance_circuit_breaker_state"),
            intent.get("paper_effective_entry_gate_state"),
        )
        or ""
    ).upper()
    if (
        paper_tier
        not in {
            PAPER_TIER_POSITIVE_EDGE_PROBATION,
            PAPER_TIER_RISK_CONTROLLER_EXPLORATION,
        }
        and any(token in guardian_state for token in ("HALTED", "BLOCKED", "SHADOW_ONLY"))
    ):
        reasons.append("GUARDIAN_HALTED_PERFORMANCE_NO_NEW_ENTRY")
    return sorted(set(reasons))


def _paper_entry_freeze_reason_texts(paper_entry_freeze: Mapping[str, Any]) -> list[str]:
    texts: list[str] = []

    def append(value: Any) -> None:
        if value in (None, "", [], {}):
            return
        if isinstance(value, Mapping):
            for nested in value.values():
                append(nested)
            return
        if isinstance(value, (list, tuple, set)):
            for nested in value:
                append(nested)
            return
        texts.append(str(value))

    for field in ("reason", "halt_reason", "halt_reasons", "source"):
        append(paper_entry_freeze.get(field))
    raw_freeze = paper_entry_freeze.get("raw_paper_entry_freeze")
    if isinstance(raw_freeze, Mapping):
        for field in ("reason", "halt_reason", "halt_reasons", "source"):
            append(raw_freeze.get(field))
    components = paper_entry_freeze.get("component_statuses")
    if isinstance(components, Mapping):
        for component in components.values():
            if isinstance(component, Mapping):
                for field in ("reason", "halt_reason", "halt_reasons", "source"):
                    append(component.get(field))
    return texts


def _paper_risk_controller_exploration_can_override_entry_freeze(
    *,
    intent: Mapping[str, Any],
    paper_entry_freeze: Mapping[str, Any],
) -> bool:
    if paper_entry_freeze.get("paper_new_entries_halted") is not True:
        return False
    if str(intent.get("paper_opportunity_tier") or "").upper() != (
        PAPER_TIER_RISK_CONTROLLER_EXPLORATION
    ):
        return False
    if (
        intent.get("paper_only") is not True
        or intent.get("routes_to_live") is True
        or intent.get("places_real_order") is True
        or intent.get("counts_as_A_plus") is True
        or intent.get("counts_as_final_a_plus") is True
        or intent.get("counts_as_live_ready") is True
    ):
        return False
    if intent.get("paper_risk_controller_exploration_eligible") is not True:
        return False
    if intent.get("paper_exploration_paper_fill_allowed") is not True:
        return False
    # Continue-with-feedback: a probation-supervisor halt (or a freeze payload
    # that explicitly allows the bootstrap lane) scopes the SUPERVISED lanes;
    # the bounded exploration lane keeps generating outcome data so the trainer
    # and floor/bucket statistics learn from the failure. The circuit-breaker
    # bucket flags below only exist when a performance circuit is active, so
    # requiring them here silently killed the learning lane in clean sessions.
    _freeze_reason_blob = " ".join(
        reason.upper() for reason in _paper_entry_freeze_reason_texts(paper_entry_freeze)
    )
    _probation_scoped_freeze = (
        paper_entry_freeze.get("bootstrap_exploration_allowed") is True
        or "PROBATION_SUPERVISOR_HALT" in _freeze_reason_blob
    )
    if not _probation_scoped_freeze:
        if intent.get("paper_performance_circuit_global_halt_only") is not True:
            return False
        if (
            intent.get("paper_risk_controller_exploration_global_halt_bucket_scoped")
            is not True
            and intent.get(
                "paper_risk_controller_exploration_global_halt_bucket_clean_allowed"
            )
            is not True
        ):
            return False
    if (
        intent.get("paper_performance_circuit_breaker_matched_blocked_bucket_keys")
        or intent.get("paper_performance_circuit_breaker_matched_loss_cluster_keys")
        or intent.get("paper_exploration_exact_blocked_bucket_keys")
    ):
        return False

    blocking_components = {
        str(component)
        for component in (paper_entry_freeze.get("blocking_components") or [])
    }
    if "churn_equity_bleed_governor" in blocking_components:
        return False

    reason_texts = _paper_entry_freeze_reason_texts(paper_entry_freeze)
    reason_blob = " ".join(reason.upper() for reason in reason_texts)
    if any(
        token in reason_blob
        for token in (
            "PORTFOLIO_TRUTH",
            "EQUITY_UNTRUSTED",
            "PNL_UNTRUSTED",
            "TRUTH_UNTRUSTED",
        )
    ):
        return False
    if (
        "manual_or_portfolio_freeze" in blocking_components
        and "PROBATION_SUPERVISOR_HALT" not in reason_blob
        and "PERFORMANCE" not in reason_blob
    ):
        return False

    symbol = str(intent.get("symbol") or "").strip().upper()
    if symbol and any(symbol in reason.upper() for reason in reason_texts):
        return False
    return True


def _paper_halted_performance_fill_exempt(row: Mapping[str, Any]) -> bool:
    tier = str(row.get("paper_opportunity_tier") or "").upper()
    if tier == PAPER_TIER_POSITIVE_EDGE_PROBATION:
        return True
    return (
        tier == PAPER_TIER_RISK_CONTROLLER_EXPLORATION
        and row.get("paper_risk_controller_exploration_overrode_entry_freeze") is True
        and row.get("paper_performance_circuit_global_halt_only") is True
        and row.get("paper_only") is True
        and row.get("routes_to_live") is not True
        and row.get("places_real_order") is not True
    )


def _apply_preemptive_admission_block(
    intent: dict[str, Any],
    reasons: list[str],
) -> None:
    intent["paper_fill_block_reason"] = reasons[0] if reasons else "PREEMPTIVE_EDGE_CONTROL_BLOCKED"
    intent["paper_fill_allowed"] = False
    intent["paper_tier_local_fill_allowed"] = False
    intent["strict_paper_fill_allowed_upstream"] = False
    intent["preemptive_admission_blocked"] = True
    intent["preemptive_admission_block_reasons"] = reasons
    intent["paper_fill_gate_block_reasons"] = sorted(set(
        list(intent.get("paper_fill_gate_block_reasons") or []) + reasons
    ))
    intent["local_block_reasons"] = sorted(set(
        list(intent.get("local_block_reasons") or [])
        + [f"preemptive_edge_control:{reason}" for reason in reasons]
    ))


def _build_preemptive_blocked_counterfactual_feedback(
    intents: list[dict[str, Any]],
    *,
    paper_session_id: str,
    generated_utc: str,
    sample_limit: int = 250,
) -> tuple[dict[str, Any], dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for intent in intents:
        if not isinstance(intent, dict):
            continue
        preemptive = (
            intent.get("preemptive_edge_control")
            if isinstance(intent.get("preemptive_edge_control"), dict)
            else {}
        )
        decision = str(
            _first_present(
                preemptive.get("preemptive_decision"),
                intent.get("preemptive_decision"),
            )
            or ""
        ).upper()
        if decision not in {"NO_TRADE", "SHADOW_ONLY"}:
            continue
        decision_id = _first_present(
            preemptive.get("preemptive_decision_id"),
            intent.get("preemptive_decision_id"),
        )
        if not decision_id:
            continue
        reasons = list(
            preemptive.get("preemptive_decision_reasons")
            or intent.get("preemptive_decision_reasons")
            or intent.get("paper_fill_gate_block_reasons")
            or []
        )
        feedback_id = f"preemptive_blocked_{decision_id}"
        rows.append({
            "schema_version": "preemptive_blocked_counterfactual_feedback_v1",
            "counterfactual_feedback_id": feedback_id,
            "trainer_feedback_source": (
                "V2_PREEMPTIVE_EDGE_CONTROL_BLOCKED_CANDIDATE"
            ),
            "paper_session_id": paper_session_id,
            "decision_time": _first_present(
                intent.get("decision_time"),
                intent.get("generated_at"),
                intent.get("signal_generated_at"),
                generated_utc,
            ),
            "available_at": _first_present(
                intent.get("available_at"),
                intent.get("signal_available_at"),
                intent.get("generated_at"),
                generated_utc,
            ),
            "feature_cutoff": _first_present(
                intent.get("feature_cutoff"),
                intent.get("feature_cutoff_at"),
            ),
            "prediction_id": _first_present(
                intent.get("prediction_id"),
                intent.get("source_prediction_id"),
                intent.get("decision_id"),
            ),
            "feature_snapshot_id": _first_present(
                intent.get("feature_snapshot_id"),
                intent.get("source_feature_snapshot_id"),
            ),
            "mtf_snapshot_id": intent.get("mtf_snapshot_id"),
            "symbol": intent.get("symbol"),
            "timeframe": _first_present(
                intent.get("timeframe"),
                intent.get("thesis_timeframe"),
            ),
            "side": _first_present(
                intent.get("side"),
                intent.get("selected_action"),
                intent.get("action"),
            ),
            "strategy_id": _first_present(
                intent.get("strategy_id"),
                intent.get("strategy_selected_mode"),
                intent.get("strategy_mode"),
            ),
            "selected_action": _first_present(
                intent.get("selected_action"),
                intent.get("action"),
                intent.get("side"),
            ),
            "preemptive_decision": decision,
            "preemptive_decision_id": decision_id,
            "preemptive_decision_reasons": reasons,
            "preemptive_action": _first_present(
                preemptive.get("preemptive_action"),
                intent.get("preemptive_action"),
            ),
            "preemptive_allowed": _first_present(
                preemptive.get("preemptive_allowed"),
                intent.get("preemptive_allowed"),
                False,
            ),
            "preemptive_block_reasons": _first_present(
                preemptive.get("preemptive_block_reasons"),
                intent.get("preemptive_block_reasons"),
                reasons,
            ),
            "reason_blocked": reasons[0] if reasons else None,
            "pre_trade_loss_probability": _first_present(
                preemptive.get("pre_trade_loss_probability"),
                intent.get("pre_trade_loss_probability"),
            ),
            "pre_trade_expected_net_pnl_usd": _first_present(
                preemptive.get("pre_trade_expected_net_pnl_usd"),
                intent.get("pre_trade_expected_net_pnl_usd"),
            ),
            "confidence_overstatement_risk": _first_present(
                preemptive.get("confidence_overstatement_risk"),
                intent.get("confidence_overstatement_risk"),
            ),
            "expected_edge": _first_present(
                preemptive.get("expected_edge_after_cost_bps"),
                intent.get("expected_move_after_cost_bps"),
            ),
            "expected_edge_after_cost_bps": _first_present(
                preemptive.get("expected_edge_after_cost_bps"),
                intent.get("expected_move_after_cost_bps"),
            ),
            "target_notional_usd": _first_present(
                preemptive.get("target_notional_usd"),
                intent.get("target_notional_usd"),
                0.0,
            ),
            # Decision-time reference price: without it the counterfactual
            # maturation lane can never compute a virtual entry and every
            # blocked-candidate row is rejected with MISSING_ENTRY_PRICE.
            "current_price": _first_present(
                intent.get("current_price"),
                intent.get("mark_price"),
                intent.get("entry_price"),
                intent.get("fill_price"),
                preemptive.get("current_price"),
            ),
            "paper_fill_allowed": False,
            "realized_future_window_label": None,
            "outcome_label": "PENDING_COUNTERFACTUAL_FUTURE_WINDOW",
            "counterfactual_label_pending": True,
            "consumable_by_trainer_now": False,
            "no_future_leakage": True,
            "paper_only": True,
            "routes_to_live": False,
            "places_real_order": False,
        })
        if len(rows) >= sample_limit:
            break

    payload = {
        "schema_version": "preemptive_blocked_counterfactual_feedback_payload_v1",
        "generated_utc": generated_utc,
        "paper_session_id": paper_session_id,
        "sample_limit": sample_limit,
        "rows": rows,
        "row_count": len(rows),
        "counterfactual_labels_pending": len(rows),
        "consumable_by_trainer_now": 0,
        "no_future_leakage": True,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    status = {
        "schema_version": "preemptive_trainer_feedback_status_v1",
        "generated_utc": generated_utc,
        "paper_session_id": paper_session_id,
        "blocked_candidate_counterfactual_rows": len(rows),
        "counterfactual_labels_pending": len(rows),
        "consumable_labeled_counterfactual_rows": 0,
        "trainer_consumption_state": (
            "PENDING_FUTURE_WINDOW_LABELS"
            if rows
            else "NO_PREEMPTIVE_BLOCKED_COUNTERFACTUAL_ROWS"
        ),
        "trainer_key": "v2:trainer:preemptive_blocked_candidates",
        "status_key": "v2:trainer:preemptive_blocked_counterfactual_status",
        "no_future_leakage": True,
        "paper_only": True,
        "routes_to_live": False,
        "places_real_order": False,
    }
    return payload, status


def _count_paper_opportunity_tiers(rows: list[dict[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        tier = str(row.get("paper_opportunity_tier") or "").strip().upper()
        if tier not in PAPER_OPPORTUNITY_TIERS:
            continue
        counts[tier] = counts.get(tier, 0) + 1
    return counts


def _missing_paper_opportunity_tier_count(rows: list[dict[str, Any]]) -> int:
    return sum(
        1
        for row in rows
        if str(row.get("paper_opportunity_tier") or "").strip().upper()
        not in PAPER_OPPORTUNITY_TIERS
    )


def _b_grade_exploration_adaptive_confidence_floor(
    *,
    drawdown_bps: Any,
    expected_move_after_cost_bps: Any = None,
    observed_spread_bps: Any = None,
    expected_slippage_bps: Any = None,
    fee_bps: Any = None,
    depth_utilization_pct: Any = None,
    long_short_ratio_status: Any = None,
) -> dict[str, Any]:
    static_floor = B_GRADE_EXPLORATION_MIN_CONFIDENCE
    max_floor = min(
        B_GRADE_EXPLORATION_ADAPTIVE_CONFIDENCE_FLOOR_MAX,
        PAPER_STRICT_A_CONFIDENCE_THRESHOLD - 0.01,
    )
    drawdown = max(0.0, _coerce_float(drawdown_bps) or 0.0)
    drawdown_pressure = _clamp_float(
        drawdown / B_GRADE_EXPLORATION_DRAWDOWN_STOP_BPS,
        0.0,
        1.0,
    )
    penalties: dict[str, float] = {
        "drawdown_pressure": round(0.10 * drawdown_pressure, 8),
        "cost_edge_pressure": 0.0,
        "depth_pressure": 0.0,
        "long_short_point_in_time_pressure": 0.0,
    }

    edge_abs = _coerce_float(expected_move_after_cost_bps)
    if edge_abs is not None:
        edge_abs = abs(edge_abs)
    cost_components = [
        max(0.0, value)
        for value in (
            _coerce_float(observed_spread_bps),
            _coerce_float(expected_slippage_bps),
            _coerce_float(fee_bps),
        )
        if value is not None
    ]
    cost_drag_bps = sum(cost_components) if cost_components else None
    edge_to_cost_ratio = None
    if cost_drag_bps is not None and cost_drag_bps > 0.0:
        if edge_abs is None or edge_abs <= 0.0:
            penalties["cost_edge_pressure"] = 0.08
        else:
            edge_to_cost_ratio = edge_abs / cost_drag_bps
            penalties["cost_edge_pressure"] = round(
                0.08 * _clamp_float((3.0 - edge_to_cost_ratio) / 3.0, 0.0, 1.0),
                8,
            )

    depth_utilization = _coerce_float(depth_utilization_pct)
    if depth_utilization is not None:
        if depth_utilization <= 1.0:
            depth_utilization *= 100.0
        penalties["depth_pressure"] = round(
            0.06 * _clamp_float(depth_utilization / 100.0, 0.0, 1.0),
            8,
        )

    long_short_status = str(long_short_ratio_status or "").strip().upper()
    if long_short_status.startswith("REJECTED_LONG_SHORT"):
        penalties["long_short_point_in_time_pressure"] = 0.04
    elif long_short_status in {"MISSING_V2_LONG_SHORT_RATIO", "REJECTED_LONG_SHORT_AVAILABLE_AT_UNPROVEN"}:
        penalties["long_short_point_in_time_pressure"] = 0.02

    raw_floor = static_floor + sum(penalties.values())
    adaptive_floor = _clamp_float(raw_floor, static_floor, max_floor)
    return {
        "b_grade_exploration_static_confidence_floor": static_floor,
        "b_grade_exploration_adaptive_confidence_floor": round(adaptive_floor, 8),
        "b_grade_exploration_adaptive_confidence_floor_max": max_floor,
        "b_grade_exploration_floor_never_below_static": adaptive_floor >= static_floor,
        "b_grade_exploration_floor_mode": (
            "ADAPTIVE_FAIL_CLOSED_CONTEXTUAL_FLOOR_NEVER_BELOW_STATIC"
        ),
        "b_grade_exploration_floor_penalties": penalties,
        "b_grade_exploration_floor_context": {
            "drawdown_bps": round(drawdown, 8),
            "drawdown_pressure": round(drawdown_pressure, 8),
            "expected_move_after_cost_bps_abs": (
                round(edge_abs, 8) if edge_abs is not None else None
            ),
            "observed_cost_drag_bps": (
                round(cost_drag_bps, 8) if cost_drag_bps is not None else None
            ),
            "edge_to_cost_ratio": (
                round(edge_to_cost_ratio, 8) if edge_to_cost_ratio is not None else None
            ),
            "depth_utilization_pct": (
                round(depth_utilization, 8) if depth_utilization is not None else None
            ),
            "long_short_ratio_status": long_short_status or None,
        },
    }


def _b_grade_exploration_budget_fraction(
    *,
    confidence_calibrated: Any,
    drawdown_bps: Any,
    expected_move_after_cost_bps: Any = None,
    observed_spread_bps: Any = None,
    expected_slippage_bps: Any = None,
    fee_bps: Any = None,
    depth_utilization_pct: Any = None,
    long_short_ratio_status: Any = None,
) -> dict[str, Any]:
    confidence = _coerce_float(confidence_calibrated)
    floor = _b_grade_exploration_adaptive_confidence_floor(
        drawdown_bps=drawdown_bps,
        expected_move_after_cost_bps=expected_move_after_cost_bps,
        observed_spread_bps=observed_spread_bps,
        expected_slippage_bps=expected_slippage_bps,
        fee_bps=fee_bps,
        depth_utilization_pct=depth_utilization_pct,
        long_short_ratio_status=long_short_ratio_status,
    )
    adaptive_floor = float(floor["b_grade_exploration_adaptive_confidence_floor"])
    drawdown = _coerce_float(drawdown_bps) or 0.0
    if confidence is None or confidence < adaptive_floor:
        return {
            **floor,
            "risk_budget_fraction_of_normal_adaptive": 0.0,
            "b_grade_exploration_uncertainty_factor": 0.0,
            "b_grade_exploration_drawdown_factor": 0.0,
            "b_grade_exploration_confidence_floor_pass": False,
            "b_grade_exploration_budget_formula": (
                "confidence_below_adaptive_b_grade_exploration_floor"
            ),
        }
    confidence_span = max(
        1e-9,
        PAPER_STRICT_A_CONFIDENCE_THRESHOLD - adaptive_floor,
    )
    confidence_progress = _clamp_float(
        (confidence - adaptive_floor) / confidence_span,
        0.0,
        1.0,
    )
    # The budget rises as uncertainty falls, then fades to zero as drawdown
    # approaches the paper-only exploration stop.
    uncertainty_factor = 0.25 + 0.75 * confidence_progress
    drawdown_pressure = _clamp_float(
        max(0.0, drawdown) / B_GRADE_EXPLORATION_DRAWDOWN_STOP_BPS,
        0.0,
        1.0,
    )
    drawdown_factor = 1.0 - drawdown_pressure
    performance = _session_performance_sizing_factor()
    performance_factor = float(performance["session_performance_sizing_factor"])
    fraction = min(
        1.0,  # never exceed the normal adaptive budget regardless of evidence
        B_GRADE_EXPLORATION_MAX_RISK_FRACTION_OF_NORMAL
        * uncertainty_factor
        * drawdown_factor
        * performance_factor,
    )
    return {
        **floor,
        **performance,
        "risk_budget_fraction_of_normal_adaptive": round(max(0.0, fraction), 8),
        "b_grade_exploration_uncertainty_factor": round(uncertainty_factor, 8),
        "b_grade_exploration_drawdown_factor": round(drawdown_factor, 8),
        "b_grade_exploration_confidence_floor_pass": True,
        "b_grade_exploration_budget_formula": (
            "min(1.0, max_fraction_of_normal_adaptive"
            "*confidence_uncertainty_factor*drawdown_guard_factor"
            "*session_performance_sizing_factor)"
        ),
    }


def _a_plus_reduced_size_bootstrap_budget_fraction(
    *,
    intent: dict[str, Any],
    confidence_calibrated: Any,
    drawdown_bps: Any,
    expected_move_after_cost_bps: Any = None,
) -> dict[str, Any]:
    base = _b_grade_exploration_budget_fraction(
        confidence_calibrated=confidence_calibrated,
        drawdown_bps=drawdown_bps,
        expected_move_after_cost_bps=expected_move_after_cost_bps,
        observed_spread_bps=_first_present(
            intent.get("actual_observed_spread_entry_bps"),
            intent.get("observed_spread_bps"),
            intent.get("bid_ask_spread_bps"),
        ),
        expected_slippage_bps=intent.get("expected_slippage_bps"),
        fee_bps=intent.get("fee_bps"),
        depth_utilization_pct=intent.get("depth_utilization_pct"),
        long_short_ratio_status=intent.get("long_short_ratio_status"),
    )
    composite = _coerce_float(intent.get("composite_microstructure_trust_score"))
    if composite is None:
        composite = _coerce_float(intent.get("microstructure_trust_score"))
    trust_gap = max(0.0, FINAL_A_PLUS_MIN_COMPOSITE_TRUST - (composite or 0.0))
    trust_gap_factor = _clamp_float(
        1.0 - (trust_gap / max(1e-9, FINAL_A_PLUS_MIN_COMPOSITE_TRUST)),
        0.05,
        1.0,
    )
    base_fraction = _coerce_float(base.get("risk_budget_fraction_of_normal_adaptive")) or 0.0
    fraction = min(
        B_GRADE_EXPLORATION_MAX_RISK_FRACTION_OF_NORMAL,
        base_fraction * trust_gap_factor,
    )
    return {
        **base,
        "risk_budget_fraction_of_normal_adaptive": round(max(0.0, fraction), 8),
        "a_plus_reduced_size_bootstrap_budget_cap_applied": True,
        "a_plus_reduced_size_bootstrap_trust_gap": round(trust_gap, 8),
        "a_plus_reduced_size_bootstrap_trust_gap_factor": round(trust_gap_factor, 8),
        "a_plus_reduced_size_bootstrap_budget_formula": (
            "b_grade_adaptive_fraction*composite_trust_gap_factor"
        ),
    }


